use filmcraft_project::{Project,ItemId,MediaRef,ParamKind,ParamValue,Keyframe};use filmcraft_time::{Tick,FrameRate};use filmcraft_media::{SharedSource,generators::GeneratorSource};use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};use std::sync::Arc;
fn main(){let input:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();const T:i64=254016000000;let mut cases=vec![];let defs:Vec<_>=filmcraft_project::effect_defs().iter().filter(|d|matches!(d.id,"wiggle"|"camera_shake"|"corner_pin")).collect();assert_eq!(defs.len(),3);
for definition in defs{for profile in 0..32{let mut effect=definition.instance();if true{for pd in &definition.params{let (lo,hi)=match &pd.kind{ParamKind::Float{min,max,..}=>{let base=pd.default.as_f64().unwrap_or(0.);(ParamValue::Float((base*0.5).clamp(*min,*max)),ParamValue::Float((base*1.5+0.25).clamp(*min,*max)))},ParamKind::Angle=>(ParamValue::Float(-27.),ParamValue::Float(53.)),_=>continue};effect.params.get_mut(pd.id).unwrap().keyframes=vec![Keyframe::new(Tick(0),lo),Keyframe::new(Tick(4*T),hi)];}}
if definition.id=="wiggle"||definition.id=="camera_shake"{effect.params.get_mut("amount").unwrap().keyframes=vec![Keyframe::new(Tick(0),ParamValue::Float(1.)),Keyframe::new(Tick(4*T),ParamValue::Float(2.5))];}
if definition.id=="camera_shake"{effect.params.get_mut("motion_blur").unwrap().keyframes=vec![Keyframe::new(Tick(0),ParamValue::Float(40.)),Keyframe::new(Tick(4*T),ParamValue::Float(80.))];}
if definition.id=="corner_pin"{
 let (control,x,y)=match profile%4{0=>("upper_left",0.,0.),1=>("upper_right",8.,0.),2=>("lower_left",0.,8.),_=>("lower_right",8.,8.)};
 let auto=filmcraft_geom::Vec2::new(f64::NAN,f64::NAN);let lo=if profile%3==2{auto}else{filmcraft_geom::Vec2::new(x-1.25,y+0.75)};let hi=if profile%3==1{auto}else{filmcraft_geom::Vec2::new(x+1.5,y-0.5)};
 effect.params.get_mut(control).unwrap().keyframes=vec![Keyframe::new(Tick(0),ParamValue::Vec2(lo)),Keyframe::new(Tick(4*T),ParamValue::Vec2(hi))];
}
let mut doc=input["cases"][profile*8+4]["document"].clone();let media=&mut doc["project"]["items"]["1"]["kind"]["Media"];media["media"]=json!({"Generator":{"Demo":"Plasma"}});media["info"]["video"]["width"]=json!(8);media["info"]["video"]["height"]=json!(8);
let seq=&mut doc["project"]["items"]["6"]["kind"]["Sequence"];seq["settings"]["width"]=json!(16);seq["settings"]["frame_rate"]=match profile%3{0=>json!({"num":24,"den":1}),1=>json!({"num":30000,"den":1001}),_=>json!({"num":60,"den":1})};seq["settings"]["height"]=json!(8);seq["caption_tracks"]=json!([]);let mut track=seq["video_tracks"][0].clone();track["enabled"]=json!(true);track["transitions"]=json!([]);let mut clip=track["items"][0].clone();clip["item"]=json!(1);if profile%2==1{clip["start"]=json!(T/4);}clip["effects"]=json!([effect]);track["items"]=json!([clip]);seq["video_tracks"]=json!([track]);let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let provider=|id:ItemId|{let(_,media,_)=p.resolve_media(id)?;let MediaRef::Generator(generator)=&media.media else{return None};Some(Arc::new(GeneratorSource::new(generator.clone(),8,8,FrameRate::new(24,1),Tick(100*T)))as SharedSource)};
for at in [2*T,9*T/4]{for scale in [1.,0.5]{let out=render_sequence(&p,ItemId(6),Tick(at),RenderOptions{scale,working_output:true,..Default::default()},&provider);cases.push(json!({"document":doc,"sequence":6,"at":at,"effect":definition.id,"profile":profile,"scale":scale,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}
}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","definitions":3,"cases":cases}));}
